15	/**
16	 * Tests memory management, including the region functionality.
17	 *
18	 * Other tests to look at include finalisers and the various cowngc tests.
19	 **/
20	
21	void test_alloc_pool()
22	{
23	#ifndef USE_MALLOC
24	  auto* a1 = current_alloc_pool()->acquire();
25	  auto* a2 = current_alloc_pool()->acquire();
26	  check(a1 != a2);
27	
28	  current_alloc_pool()->release(a1);
29	  auto* a3 = current_alloc_pool()->acquire();
30	  check(a3 == a1);
31	
32	  current_alloc_pool()->release(a2);
33	  current_alloc_pool()->release(a3);
34	  snmalloc::current_alloc_pool()->debug_check_empty();
35	#endif
36	}
37	
38	void test_dealloc()
39	{
40	  auto* alloc = ThreadAlloc::get();
41	
42	  size_t size = 1 << 25;
43	  void* p = alloc->alloc(size);
44	  alloc->dealloc(p, size);
45	
46	  snmalloc::current_alloc_pool()->debug_check_empty();
47	}
48	
49	size_t do_nothing(size_t x);
50	
51	int main(int argc, char** argv)
52	{
53	  opt::Opt opt(argc, argv);
54	  size_t seed = opt.is<size_t>("--seed", 0);
55	  seed = do_nothing(seed);
56	#ifdef USE_SYSTEMATIC_TESTING
57	#  ifdef WIN32
58	//  TODO: Not currently supported by snmalloc
59	//  default_memory_provider().systematic_bump_ptr() += seed << 17;
60	#  endif
61	#endif
62	
63	  memory_alloc::run_test();
64	  memory_iterator::run_test();
65	  memory_swap_root::run_test();
66	  memory_merge::run_test();
67	  memory_gc::run_test();
68	  memory_subregion::run_test();
69	
70	  test_alloc_pool();
71	  test_dealloc();
72	
73	  return 0;
74	}
